import React, { useEffect, useState } from 'react';
import { FiDollarSign, FiTrendingUp, FiShoppingCart, FiCheckCircle } from 'react-icons/fi';
import { LineChart, Line, AreaChart, Area, BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import './metrics.css';

const RevenueMetrics = () => {
  const [revenueData, setRevenueData] = useState({
    totalRevenue: 45230,
    monthlyRevenue: 12450,
    totalTransactions: 8943,
    completedTransactions: 8230,
    pendingTransactions: 520,
    failedTransactions: 193,
    averageTransactionValue: 52.80,
    conversionRate: 92.0,
    revenueByMonth: [],
    revenueBySource: [],
    transactionBreakdown: [],
    topTransactions: []
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchRevenueData = async () => {
      try {
        const mockData = {
          totalRevenue: 45230,
          monthlyRevenue: 12450,
          totalTransactions: 8943,
          completedTransactions: 8230,
          pendingTransactions: 520,
          failedTransactions: 193,
          averageTransactionValue: 52.80,
          conversionRate: 92.0,
          revenueByMonth: [
            { month: 'Jan', revenue: 8500, transactions: 1250 },
            { month: 'Feb', revenue: 9200, transactions: 1380 },
            { month: 'Mar', revenue: 10500, transactions: 1580 },
            { month: 'Apr', revenue: 11200, transactions: 1750 },
            { month: 'May', revenue: 12450, transactions: 1983 }
          ],
          revenueBySource: [
            { source: 'Premium Subscriptions', value: 28000, percentage: 61.8 },
            { source: 'Job Listings', value: 12000, percentage: 26.5 },
            { source: 'Featured Profiles', value: 4500, percentage: 9.9 },
            { source: 'Other Services', value: 730, percentage: 1.6 }
          ],
          transactionBreakdown: [
            { status: 'Completed', count: 8230, percentage: 92.0, color: '#00d973' },
            { status: 'Pending', count: 520, percentage: 5.8, color: '#ffd700' },
            { status: 'Failed', count: 193, percentage: 2.2, color: '#ff4444' }
          ],
          topTransactions: [
            { id: 'TRX-001', user: 'John Doe', type: 'Premium Pro', amount: 299.99, date: '2024-03-29', status: 'Completed' },
            { id: 'TRX-002', user: 'Jane Smith', type: 'Job Listing', amount: 49.99, date: '2024-03-28', status: 'Completed' },
            { id: 'TRX-003', user: 'Mike Johnson', type: 'Premium Pro', amount: 199.99, date: '2024-03-28', status: 'Completed' },
            { id: 'TRX-004', user: 'Sarah Wilson', type: 'Featured Profile', amount: 29.99, date: '2024-03-27', status: 'Pending' },
            { id: 'TRX-005', user: 'Tom Brown', type: 'Premium', amount: 89.99, date: '2024-03-27', status: 'Completed' }
          ]
        };
        setRevenueData(mockData);
      } catch (error) {
        console.error('Failed to fetch revenue data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchRevenueData();
  }, []);

  if (loading) {
    return <div style={{ padding: 20, color: '#8696a0' }}>Loading...</div>;
  }

  const transactionColors = {
    'Completed': '#00d973',
    'Pending': '#ffd700',
    'Failed': '#ff6b6b'
  };

  const sourceColors = ['#00d4ff', '#00d973', '#ff9500', '#ff6b6b', '#9c27b0'];

  // Custom color palette for better charts
  const chartColors = {
    primary: '#00d4ff',
    success: '#00d973',
    warning: '#ffd700',
    error: '#ff6b6b',
    info: '#9c27b0'
  };

  return (
    <div style={{ padding: '24px' }}>
      {/* Header */}
      <div style={{ marginBottom: '28px' }}>
        <h1 style={{ fontSize: '28px', fontWeight: '700', color: '#ffffff', margin: 0, letterSpacing: '-0.5px' }}>Revenue Metrics</h1>
        <p style={{ fontSize: '13px', color: '#8696a0', margin: '6px 0 0 0' }}>Monitor financial performance and transaction activity</p>
      </div>

      {/* Summary Stats Cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '16px', marginBottom: '32px' }}>
        <div style={{ padding: '18px', background: 'linear-gradient(135deg, rgba(0, 217, 115, 0.12) 0%, rgba(0, 217, 115, 0.04) 100%)', border: '1px solid rgba(0, 217, 115, 0.2)', borderRadius: '10px', backdropFilter: 'blur(10px)' }}>
          <div style={{ fontSize: '11px', color: '#8696a0', marginBottom: '10px', textTransform: 'uppercase', letterSpacing: '0.6px', fontWeight: '500' }}>Total Revenue</div>
          <div style={{ fontSize: '28px', fontWeight: '700', color: '#00d973', lineHeight: 1 }}>${revenueData.totalRevenue.toLocaleString()}</div>
        </div>
        <div style={{ padding: '18px', background: 'linear-gradient(135deg, rgba(0, 217, 115, 0.12) 0%, rgba(0, 217, 115, 0.04) 100%)', border: '1px solid rgba(0, 217, 115, 0.2)', borderRadius: '10px', backdropFilter: 'blur(10px)' }}>
          <div style={{ fontSize: '11px', color: '#8696a0', marginBottom: '10px', textTransform: 'uppercase', letterSpacing: '0.6px', fontWeight: '500' }}>This Month</div>
          <div style={{ fontSize: '28px', fontWeight: '700', color: '#00d973', lineHeight: 1 }}>${revenueData.monthlyRevenue.toLocaleString()}</div>
        </div>
        <div style={{ padding: '18px', background: 'linear-gradient(135deg, rgba(0, 212, 255, 0.12) 0%, rgba(0, 212, 255, 0.04) 100%)', border: '1px solid rgba(0, 212, 255, 0.2)', borderRadius: '10px', backdropFilter: 'blur(10px)' }}>
          <div style={{ fontSize: '11px', color: '#8696a0', marginBottom: '10px', textTransform: 'uppercase', letterSpacing: '0.6px', fontWeight: '500' }}>Total Transactions</div>
          <div style={{ fontSize: '28px', fontWeight: '700', color: '#00d4ff', lineHeight: 1 }}>{revenueData.totalTransactions.toLocaleString()}</div>
        </div>
        <div style={{ padding: '18px', background: 'linear-gradient(135deg, rgba(255, 215, 0, 0.12) 0%, rgba(255, 215, 0, 0.04) 100%)', border: '1px solid rgba(255, 215, 0, 0.2)', borderRadius: '10px', backdropFilter: 'blur(10px)' }}>
          <div style={{ fontSize: '11px', color: '#8696a0', marginBottom: '10px', textTransform: 'uppercase', letterSpacing: '0.6px', fontWeight: '500' }}>Avg Transaction</div>
          <div style={{ fontSize: '28px', fontWeight: '700', color: '#ffd700', lineHeight: 1 }}>${revenueData.averageTransactionValue.toFixed(2)}</div>
        </div>
      </div>

      {/* Charts Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(450px, 1fr))', gap: '20px', marginBottom: '32px' }}>
        {/* Revenue Trend - Full width on mobile */}
        <div style={{ gridColumn: 'auto', padding: '20px', background: 'rgba(13, 27, 42, 1)', border: '1px solid rgba(134, 150, 160, 0.1)', borderRadius: '12px', boxShadow: '0 4px 20px rgba(0, 0, 0, 0.3)' }}>
          <h3 style={{ marginBottom: '18px', color: '#ffffff', fontSize: '15px', fontWeight: '600', margin: 0 }}>Revenue Trend</h3>
          <ResponsiveContainer width="100%" height={280}>
            <AreaChart data={revenueData.revenueByMonth} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor={chartColors.primary} stopOpacity={0.25}/>
                  <stop offset="95%" stopColor={chartColors.primary} stopOpacity={0}/>
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(134, 150, 160, 0.08)" vertical={false} />
              <XAxis dataKey="month" stroke="rgba(134, 150, 160, 0.3)" style={{ fontSize: '12px' }} />
              <YAxis stroke="rgba(134, 150, 160, 0.3)" style={{ fontSize: '12px' }} />
              <Tooltip 
                contentStyle={{ backgroundColor: 'rgba(11, 20, 26, 0.95)', border: '1px solid rgba(0, 212, 255, 0.3)', borderRadius: '8px', boxShadow: '0 8px 24px rgba(0, 0, 0, 0.5)' }}
                formatter={(value) => `$${value.toLocaleString()}`}
              />
              <Area type="monotone" dataKey="revenue" stroke={chartColors.primary} strokeWidth={2.5} fillOpacity={1} fill="url(#colorRevenue)" />
            </AreaChart>
          </ResponsiveContainer>
        </div>

        {/* Transaction Status Pie */}
        <div style={{ padding: '20px', background: 'rgba(13, 27, 42, 1)', border: '1px solid rgba(134, 150, 160, 0.1)', borderRadius: '12px', boxShadow: '0 4px 20px rgba(0, 0, 0, 0.3)' }}>
          <h3 style={{ marginBottom: '18px', color: '#ffffff', fontSize: '15px', fontWeight: '600', margin: 0 }}>Transaction Status</h3>
          <ResponsiveContainer width="100%" height={280}>
            <PieChart>
              <Pie
                data={revenueData.transactionBreakdown}
                cx="50%"
                cy="50%"
                labelLine={true}
                label={({ status, percent }) => `${status}\n${(percent * 100).toFixed(0)}%`}
                outerRadius={85}
                fill="#8884d8"
                dataKey="count"
              >
                {revenueData.transactionBreakdown.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={transactionColors[entry.status] || '#8696a0'} />
                ))}
              </Pie>
              <Tooltip contentStyle={{ backgroundColor: 'rgba(11, 20, 26, 0.95)', border: '1px solid rgba(0, 212, 255, 0.3)', borderRadius: '8px', boxShadow: '0 8px 24px rgba(0, 0, 0, 0.5)' }} formatter={(value) => `${value.toLocaleString()}`} />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Revenue by Source - Full Width */}
      <div style={{ padding: '20px', background: 'rgba(13, 27, 42, 1)', border: '1px solid rgba(134, 150, 160, 0.1)', borderRadius: '12px', boxShadow: '0 4px 20px rgba(0, 0, 0, 0.3)', marginBottom: '32px' }}>
        <h3 style={{ marginBottom: '18px', color: '#ffffff', fontSize: '15px', fontWeight: '600', margin: 0 }}>Revenue by Source</h3>
        <ResponsiveContainer width="100%" height={300}>
          <PieChart>
            <Pie
              data={revenueData.revenueBySource}
              cx="50%"
              cy="50%"
              labelLine={true}
              label={({ source, percent }) => `${source} ${(percent * 100).toFixed(0)}%`}
              outerRadius={100}
              fill="#8884d8"
              dataKey="value"
            >
              {revenueData.revenueBySource.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={sourceColors[index % sourceColors.length]} />
              ))}
            </Pie>
            <Tooltip contentStyle={{ backgroundColor: 'rgba(11, 20, 26, 0.95)', border: '1px solid rgba(0, 212, 255, 0.3)', borderRadius: '8px', boxShadow: '0 8px 24px rgba(0, 0, 0, 0.5)' }} formatter={(value) => `$${value.toLocaleString()}`} />
          </PieChart>
        </ResponsiveContainer>
      </div>

      {/* Recent Transactions Table */}
      <div style={{ padding: '20px', background: 'rgba(13, 27, 42, 1)', border: '1px solid rgba(134, 150, 160, 0.1)', borderRadius: '12px', boxShadow: '0 4px 20px rgba(0, 0, 0, 0.3)' }}>
        <h3 style={{ marginBottom: '18px', color: '#ffffff', fontSize: '15px', fontWeight: '600', margin: 0 }}>Recent Transactions</h3>
        <div style={{ overflowX: 'auto' }}>
          <table className="table" style={{ borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '1px solid rgba(134, 150, 160, 0.15)' }}>
                <th style={{ padding: '12px 8px', textAlign: 'left', fontSize: '12px', color: '#8696a0', fontWeight: '500', textTransform: 'uppercase', letterSpacing: '0.5px' }}>#</th>
                <th style={{ padding: '12px 8px', textAlign: 'left', fontSize: '12px', color: '#8696a0', fontWeight: '500', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Transaction ID</th>
                <th style={{ padding: '12px 8px', textAlign: 'left', fontSize: '12px', color: '#8696a0', fontWeight: '500', textTransform: 'uppercase', letterSpacing: '0.5px' }}>User</th>
                <th style={{ padding: '12px 8px', textAlign: 'left', fontSize: '12px', color: '#8696a0', fontWeight: '500', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Type</th>
                <th style={{ padding: '12px 8px', textAlign: 'left', fontSize: '12px', color: '#8696a0', fontWeight: '500', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Amount</th>
                <th style={{ padding: '12px 8px', textAlign: 'left', fontSize: '12px', color: '#8696a0', fontWeight: '500', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Date</th>
                <th style={{ padding: '12px 8px', textAlign: 'left', fontSize: '12px', color: '#8696a0', fontWeight: '500', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Status</th>
              </tr>
            </thead>
            <tbody>
              {revenueData.topTransactions.map((txn, idx) => (
                <tr key={idx} style={{ borderBottom: '1px solid rgba(134, 150, 160, 0.08)', transition: 'background 0.2s ease' }} onMouseEnter={(e) => e.currentTarget.style.background = 'rgba(0, 212, 255, 0.05)'} onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}>
                  <td style={{ padding: '12px 8px', fontSize: '13px', color: '#d0d8e0' }}>{idx + 1}</td>
                  <td style={{ padding: '12px 8px', fontSize: '12px', color: '#8696a0', fontFamily: 'monospace' }}>{txn.id}</td>
                  <td style={{ padding: '12px 8px', fontSize: '13px', color: '#d0d8e0' }}>{txn.user}</td>
                  <td style={{ padding: '12px 8px', fontSize: '13px', color: '#8696a0' }}>{txn.type}</td>
                  <td style={{ padding: '12px 8px', fontSize: '13px', color: chartColors.success, fontWeight: '600' }}>${txn.amount.toFixed(2)}</td>
                  <td style={{ padding: '12px 8px', fontSize: '13px', color: '#8696a0' }}>{new Date(txn.date).toLocaleDateString()}</td>
                  <td style={{ padding: '12px 8px', fontSize: '13px', color: transactionColors[txn.status] || '#8696a0', fontWeight: '600' }}>{txn.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginTop: '16px', paddingTop: '16px', borderTop: '1px solid rgba(134, 150, 160, 0.1)' }}>
          <div style={{ fontSize: '12px', color: '#8696a0' }}>Showing {revenueData.topTransactions.length} recent transactions</div>
        </div>
      </div>
    </div>
  );
};

export default RevenueMetrics;
